"""Generate the one-to-one BMP uppercase table used for ordinal UTF-16 comparison."""

from pathlib import Path
import unicodedata


def main():
    target = Path(__file__).resolve().parents[1] / "user/w/kernel32/UnicodeUpper.inc"
    mappings = []
    for codepoint in range(0x10000):
        upper = chr(codepoint).upper()
        if len(upper) == 1 and ord(upper) != codepoint and ord(upper) < 0x10000:
            mappings.append((codepoint, ord(upper)))
    lines = [
        "/* Generated by tools/GenerateUnicodeUpper.py from Python Unicode "
        + unicodedata.unidata_version + ". */",
        "static const struct { WCHAR From, To; } g_unicode_upper[] = {",
    ]
    for source, upper in mappings:
        lines.append(f"    {{0x{source:04X}, 0x{upper:04X}}},")
    lines.append("};")
    target.write_text("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
